-- 000004_user_api_keys.up.sql
--
-- API keys are generated by UserService.GenerateAPIKey and looked up by
-- UserService.DecodeAPIKey. The User model carries them as APIKey/Keys
-- (db:"-"), so they are stored as JSONB next to the user row:
-- api_key holds the active key object, api_keys the full history.

ALTER TABLE users ADD COLUMN IF NOT EXISTS api_key JSONB NOT NULL DEFAULT '{}';
ALTER TABLE users ADD COLUMN IF NOT EXISTS api_keys JSONB NOT NULL DEFAULT '[]';
